SELECT MAX(AUTO_SUSPEND_SECONDS) AS "WH_AUTOSUSPEND_SECONDS" FROM (SELECT "NAME" AS WAREHOUSE_NAME, "SIZE" AS WAREHOUSE_SIZE, "TYPE" AS WAREHOUSE_TYPE, "AUTO_SUSPEND" AS AUTO_SUSPEND_SECONDS, "MIN_CLUSTER_COUNT" AS MIN_CLUSTERS, "MAX_CLUSTER_COUNT" AS MAX_CLUSTERS, "SCALING_POLICY" AS SCALING_POLICY, "OWNER" AS OWNER_ROLE, "RESOURCE_MONITOR" AS RESOURCE_MONITOR, "COMMENT" AS WAREHOUSE_COMMENT FROM warehouses) AS base ORDER BY "WH_AUTOSUSPEND_SECONDS" DESC LIMIT 100
